  ["forever.mage-frost.s4.low2.why"] = "half your mana regeneration continues while casting",
  ["forever.mage-frost.s4.low3.if"] = "when your mana is nearly gone",
  ["forever.mage-frost.s4.low3.why"] = "the wand costs no mana, but you must stand still",
  ["forever.mage-frost.s4.opening1.if"] = "when it has run out",
  ["forever.mage-frost.s4.opening1.why"] = "it shields you and raises your Frost damage",
