  ["forever.rogue-assassination.s3.loop5.why"] = "it builds the points when Backstab cannot",
  ["forever.rogue-assassination.s3.low1.if"] = "when your Energy is empty",
  ["forever.rogue-assassination.s3.low1.why"] = "swings still land while Energy comes back",
  ["forever.rogue-assassination.s3.opening1.if"] = "before the pull, out of combat",
  ["forever.rogue-assassination.s3.opening1.text"] = "Open at full Energy",
  ["forever.rogue-assassination.s3.opening1.why"] = "Poised takes Energy off your first ability",
  ["forever.rogue-assassination.s3.opening2.if"] = "before the pull, if you can reach it unseen",
