  ["forever.rogue-assassination.s3.rarely1.why"] = "it stops the cast",
  ["forever.rogue-assassination.s3.rarely2.if"] = "when a fight goes wrong",
  ["forever.rogue-assassination.s3.rarely2.why"] = "the monster loses you and you can bandage",
  ["forever.rogue-assassination.s3.rarely3.if"] = "on a monster you cannot beat in the open",
  ["forever.rogue-assassination.s3.rarely3.why"] = "each point is a second of stun",
  ["forever.rogue-assassination.s3.rarely4.if"] = "when a second monster joins",
  ["forever.rogue-assassination.s3.rarely4.why"] = "it holds one still while you kill the other",
  ["forever.rogue-assassination.s3.rarely5.if"] = "when a monster hits hard",
  ["forever.rogue-assassination.s3.rarely5.why"] = "you dodge more while it lasts",
  ["forever.rogue-assassination.s3.rarely6.if"] = "to get away from a monster you cannot beat",
  ["forever.rogue-assassination.s3.rarely6.why"] = "it wanders off blind while you leave",
  ["forever.rogue-assassination.s4"] = "Mutilate at 42 is the build. Daggers, a poison on each, Shank on cooldown. Slice and Dice gets stronger at 42.",
