  ["forever.rogue-assassination.s4.rarely1.why"] = "it stops the cast",
  ["forever.rogue-assassination.s4.rarely2.if"] = "when a fight goes wrong",
  ["forever.rogue-assassination.s4.rarely2.why"] = "the monster loses you and you can bandage",
  ["forever.rogue-assassination.s4.rarely3.if"] = "on a monster you cannot beat in the open",
  ["forever.rogue-assassination.s4.rarely3.why"] = "each point is a second of stun",
  ["forever.rogue-assassination.s4.rarely4.if"] = "when a second monster joins",
  ["forever.rogue-assassination.s4.rarely4.why"] = "it holds one still while you kill the other",
