  ["forever.rogue-combat.s1.loop3.if"] = "when the monster is about to die",
  ["forever.rogue-combat.s1.loop3.why"] = "left-over points are wasted when it dies",
  ["forever.rogue-combat.s1.loop4.why"] = "it hits and builds the points Eviscerate spends",
